<script setup>
import {computed,ref,shallowRef,watch,onBeforeUnmount} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';
import {newLightShow,validateLightShow,lightFrame} from '../../room/creativeTools.js';
import {useLocalDraft} from '../../composables/useLocalDraft.js';
import {useInteractionAudio} from '../../composables/useInteractionAudio.js';
import {defaultPattern,validatePattern,patternSounds} from '../../room/pattern.js';
import {loadLocal,downloadJson} from '../../room/storage.js';
import {downloadStage} from '../../room/exportImage.js';
import {cast} from '../../data/playroom.js';
import {recordActivity} from '../../room/activityLog.js';
const {state,saved}=useLocalDraft('hitori-room:lights:v1',newLightShow(),validateLightShow),audio=useInteractionAudio('lights'),svg=ref(null),track=ref(0),step=ref(0),fraction=ref(0),playing=ref(false),sync=ref(false),message=ref('点选时间轴上的一格，调整这一拍的光。'),background=shallowRef('');
const cue=computed(()=>state.value.cues[track.value][step.value]),lights=computed(()=>lightFrame(state.value,step.value,fraction.value)),pattern=ref(loadLocal('hitori-room:studio:v1',defaultPattern,validatePattern));
const asset=path=>`${import.meta.env.BASE_URL}${path}`;
try{const value=localStorage.getItem('hitori-room:stage-background:v1');if(value?.length<1500000&&/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(value))background.value=value;}catch{}
let frame=0,start=0,generation=0;
function stop(){generation++;cancelAnimationFrame(frame);frame=0;playing.value=false;fraction.value=0;audio.stop();}
function tick(now){const beat=60000/state.value.bpm/4,elapsed=now-start,next=Math.floor(elapsed/beat)%16;fraction.value=(elapsed%beat)/beat;if(next!==step.value){step.value=next;if(sync.value)for(const sound of patternSounds(pattern.value,next))audio.play(sound.sound,sound.frequency);}frame=requestAnimationFrame(tick);}
async function play(){stop();const token=++generation;pattern.value=loadLocal('hitori-room:studio:v1',defaultPattern,validatePattern);if(sync.value){state.value.bpm=pattern.value.bpm;if(!await audio.setEnabled(true)){message.value='声音暂不可用，可以关闭同步后预览灯光。';return;}}if(token!==generation||document.hidden)return;step.value=0;playing.value=true;start=performance.now();if(sync.value)for(const sound of patternSounds(pattern.value,0))audio.play(sound.sound,sound.frequency);frame=requestAnimationFrame(tick);}
function select(t,s){stop();track.value=t;step.value=s;}
async function png(){try{await downloadStage(svg.value,'hitori-light-stage.png');recordActivity('lights',state.value.name);message.value='这一束光，已经导出成图片。';}catch{message.value='图片导出失败，请再试一次。';}}
function json(){downloadJson(validateLightShow(state.value),'hitori-lights.json');recordActivity('lights',state.value.name);}
async function upload(e){const file=e.target.files?.[0];if(!file)return;stop();try{if(file.size>32768)throw new Error('灯光文件不能超过 32 KiB。');state.value=validateLightShow(JSON.parse(await file.text()));message.value='灯光编排已读入。';}catch(error){message.value=error.message||'文件无法读取，原编排还在。';}e.target.value='';}
function hidden(){if(document.hidden)stop();}document.addEventListener('visibilitychange',hidden);onBeforeRouteLeave(stop);onBeforeUnmount(()=>{stop();document.removeEventListener('visibilitychange',hidden);});
watch(audio.enabled,value=>{if(!value&&sync.value)stop();});
</script>
<template><section class="room-panel" aria-labelledby="lights-title"><div class="pg-heading"><div><p class="pg-kicker">DRAW WITH THE LIGHT / 光にも、四拍子</p><h2 id="lights-title">今晚的舞台，由你点亮。</h2><p class="room-intro">三束光、十六步时间轴。逐步安排位置与亮度，淡入下一格，也能跟随本机保存的编曲。</p></div><span class="pg-number">17</span></div><div class="pg-board"><svg ref="svg" viewBox="0 0 900 520" role="img" aria-label="灯光舞台预览"><defs><linearGradient v-for="(l,i) in lights" :id="`stage-beam-${i}`" :key="i" x2="0" y2="1"><stop :stop-color="l.color" stop-opacity=".65"/><stop offset="1" :stop-color="l.color" stop-opacity=".08"/></linearGradient></defs><rect width="900" height="520" fill="#292334"/><image v-if="state.background&&background" :href="background" width="900" height="445" preserveAspectRatio="xMidYMid slice" opacity=".65"/><path d="M0 50Q130 140 260 50Q390 140 520 50Q650 140 780 50Q850 105 900 50V0H0Z" fill="#57425b"/><rect y="430" width="900" height="90" fill="#604e65"/><g v-for="(l,i) in lights" :key="i" :opacity="l.intensity"><path :d="`M${150+i*300} 35L${l.x-170} 445L${l.x+170} 445Z`" :fill="`url(#stage-beam-${i})`"/><ellipse :cx="l.x" cy="438" rx="170" ry="25" :fill="l.color" opacity=".5"/></g><image v-for="(member,i) in cast" :key="member.id" :href="asset(member.image)" :x="150+i*170" y="275" width="110" height="165"/><text x="450" y="492" text-anchor="middle" fill="#ead9df" font-size="20" letter-spacing="3">{{state.name||'TONIGHT AT STARRY'}}</text></svg></div>
<div class="pg-toolbar"><button id="lights-play" class="primary" :disabled="playing" @click="play">预览十六步 ↻</button><button :disabled="!playing" @click="stop">停止</button><label class="pg-small"><input v-model="sync" type="checkbox" :disabled="playing"> 同步本机编曲与声音</label><span class="pg-small">第 {{step+1}} / 16 步</span></div><div class="light-timeline" aria-label="灯光时间轴"><div v-for="(row,t) in state.cues" :key="t"><span>灯 {{t+1}}</span><button v-for="(c,s) in row" :key="s" :aria-label="`灯 ${t+1} 第 ${s+1} 步`" :aria-pressed="t===track&&s===step" :style="{background:c.color,opacity:.4+c.intensity*.6}" :class="{'light-playing':playing&&s===step}" @click="select(t,s)">{{s+1}}</button></div></div>
<div class="pg-split pg-surface"><div class="pg-settings"><label>作品名称<input v-model="state.name" maxlength="60"></label><label>速度 · {{state.bpm}} BPM<input v-model.number="state.bpm" type="range" min="60" max="180" :disabled="playing"></label><label><input v-model="state.background" type="checkbox" :disabled="!background"> 使用涂鸦墙保存的背景</label><p class="pg-small">{{background?'已读取本机的舞台背景。':'到涂鸦墙画一张，再选择「用作舞台背景」。'}}</p></div><fieldset class="pg-settings" :disabled="playing"><legend>灯 {{track+1}} · 第 {{step+1}} 步</legend><label>落点 · {{Math.round(cue.x)}}<input id="light-position" v-model.number="cue.x" type="range" min="50" max="850"></label><label>亮度 · {{Math.round(cue.intensity*100)}}%<input id="light-intensity" v-model.number="cue.intensity" type="range" min="0" max="1" step=".05"></label><label>颜色<input v-model="cue.color" type="color"></label><label><input v-model="cue.fade" type="checkbox"> 平滑过渡到下一格的位置与亮度</label><button @click="state.cues[track]=state.cues[track].map(()=>({...cue}))">复制这一格到整束灯</button></fieldset></div><div class="pg-toolbar"><button id="lights-png" @click="png">导出舞台 PNG</button><button @click="json">导出编排 JSON</button><label class="room-file-button">导入 JSON<input type="file" accept="application/json,.json" @change="upload"></label><button @click="stop();state=newLightShow()">恢复最初的光</button></div><p class="pg-status" role="status">{{message}}</p><p class="pg-small">{{saved?'编排自动保存在本机。':'存档暂不可用。'}} 切到其他页面或窗口时，预览和声音会停止。</p></section></template>
<style scoped>.light-timeline{overflow-x:auto;padding:8px 0}.light-timeline>div{display:grid;grid-template-columns:45px repeat(16,minmax(30px,1fr));gap:5px;min-width:650px;margin-bottom:8px}.light-timeline span{align-self:center;font-size:11px}.light-timeline button{padding:8px 0;font-size:10px;color:#46334e;min-height:35px;border-color:transparent}.light-timeline button[aria-pressed=true]{outline:2px solid #5e3c61;outline-offset:1px}.light-playing{box-shadow:inset 0 -5px #53395b}fieldset{min-width:0;border:1px solid #bb9db2;padding:16px}legend{font-size:12px}input[type=color]{height:40px;min-width:65px}.pg-settings label:has(input[type=checkbox]){display:flex;gap:9px;align-items:center;font-size:12px}</style>
